const { withAndroidManifest, createRunOncePlugin } = require('@expo/config-plugins')

/**
 * Permits cleartext (HTTP) traffic on Android.
 *
 * The BizSawa dev API is reached over HTTP to a LAN host
 * (EXPO_PUBLIC_API_URL, e.g. http://192.168.x.x:5504/api/v1). Android 9+
 * (targetSdk 36) blocks cleartext HTTP by default, so every API call from a
 * physical device fails with "Network Error". Production uses HTTPS
 * (https://api.bizsawa.chrismwiti.me), so this flag only affects dev/LAN.
 *
 * Because `mobile/android/` is gitignored and regenerated by `npx expo
 * prebuild`, editing AndroidManifest.xml by hand does not stick. This plugin
 * reapplies the flag on every prebuild.
 */
const withAndroidCleartextTraffic = (config) => {
  return withAndroidManifest(config, (cfg) => {
    const manifest = cfg.modResults.manifest
    const application = manifest.application
    const set = (app) => {
      app.$ = app.$ || {}
      app.$['android:usesCleartextTraffic'] = 'true'
    }
    if (Array.isArray(application)) {
      application.forEach(set)
    } else if (application) {
      set(application)
    }
    return cfg
  })
}

module.exports = createRunOncePlugin(
  withAndroidCleartextTraffic,
  'bizsawa-android-cleartext-traffic',
  '1.0.0'
)
